import { Injectable } from '@angular/core';
import { MouseDataService } from './mouse-data.service';


export interface MouseEventData {
  x: number;
  y: number;
  timestamp: number;
  xNorm: number;  // NOVO
  yNorm: number;  // NOVO
}

@Injectable({
  providedIn: 'root'
})
export class MouseTrackerService {

  constructor(private mouseDataService: MouseDataService) { }
  private data: MouseEventData[] = [];
  private tracking = false;
  private case = '';

  private track = (e: MouseEvent) => {
    const x = e.clientX;
    const y = e.clientY;
    const w = window.innerWidth;
    const h = window.innerHeight;

    this.data.push({
      x,
      y,
      timestamp: Date.now(),
      xNorm: +(x / w).toFixed(4),
      yNorm: +(y / h).toFixed(4)
    });
  };

  startTracking(t: string) {
    if (!this.tracking) {
      document.addEventListener('mousemove', this.track);
      this.tracking = true;
      this.case = t;
    }
  }

  stopTracking() {
    if (this.tracking) {
      document.removeEventListener('mousemove', this.track);
      this.tracking = false;
      const movements = [...this.data]; // kopija da ne gubimo referencu
      const sessionId = localStorage.getItem('sessionId');

      if (!sessionId) {
        console.error('[MouseTracker] Nema sessionId u localStorage!');
        return;
      }


      this.mouseDataService.sendMouseData(this.case, movements, sessionId).subscribe({
        next: () => console.log(`[MouseTracker] Podaci poslati za test: ${this.case}`),
        error: (err) => console.error('[MouseTracker] Greška pri slanju:', err)
      });

      this.case = '';
    }
  }

  getData(): MouseEventData[] {
    return this.data;
  }

  clear() {
    this.data = [];
    this.tracking = false;
  }

}
